const body = $input.first().json.body || $input.first().json;
const ipRegex = /^(?:\d{1,3}\.){3}\d{1,3}$/;
const sourceIp = ipRegex.test(body.source_ip || '') ? body.source_ip : null;
const downloads = (body.event && body.event.downloads) || [];
return [{ json: {
  session: {
    timestamp: body.timestamp || new Date().toISOString(),
    session_id: String(body.session_id || 'unknown').slice(0, 64),
    source_ip: sourceIp,
    host: body.host || 'unknown',
    instance_id: body.instance_id || '',
    event: body.event || {},
    hints: body.hints || {}
  },
  first_sha256: downloads.length ? downloads[0].sha256 : null,
  first_url: downloads.length ? downloads[0].url : null,
  needs_vt: !!sourceIp
}}];

const base = $('2. Extract IP & Session').first().json;
let vtIp = { skipped: true, malicious: 0, suspicious: 0, country: null, as_owner: null, reputation: null };
let vtFile = { skipped: true, malicious: 0, suspicious: 0, type_description: null, names: [] };
try {
  for (const item of $input.all()) {
    const attrs = item.json && item.json.data && item.json.data.attributes;
    if (!attrs) continue;
    if (attrs.last_analysis_stats && attrs.country !== undefined) {
      vtIp = { skipped: false, malicious: attrs.last_analysis_stats.malicious, suspicious: attrs.last_analysis_stats.suspicious, harmless: attrs.last_analysis_stats.harmless, country: attrs.country, as_owner: attrs.as_owner, reputation: attrs.reputation };
    }
    if (attrs.last_analysis_stats && attrs.type_description) {
      vtFile = { skipped: false, malicious: attrs.last_analysis_stats.malicious, suspicious: attrs.last_analysis_stats.suspicious, type_description: attrs.type_description, names: (attrs.names || []).slice(0, 5) };
    }
  }
} catch(e) {}
return [{ json: { session: base.session, virustotal_ip: vtIp, virustotal_files: vtFile } }];

const prev = $('4. Enrich Context').first().json;
let analysis;
try { analysis = JSON.parse($input.first().json.choices[0].message.content); }
catch(e) { analysis = { summary: 'LLM parse failed - escalate to human, do not auto-block', attacker_goal: 'unknown', mitre: [], iocs: {}, is_bot: false, severity: 'medium', confidence: 0, recommended_action: 'escalate_human' }; }
const ev = prev.session.event || {};
const hasDownload = !!(ev.downloads && ev.downloads.length);
const hasExecution = !!(prev.session.hints && prev.session.hints.has_execution);
const vtIpMal = prev.virustotal_ip.malicious || 0;
const vtFileMal = prev.virustotal_files.malicious || 0;
const shouldBlock =
  vtIpMal >= 5 ||
  vtFileMal >= 3 ||
  ((hasDownload || hasExecution) && analysis.confidence >= 70 && ['high','critical'].includes(analysis.severity));
return [{ json: { session: prev.session, virustotal_ip: prev.virustotal_ip, virustotal_files: prev.virustotal_files, analysis, should_block: shouldBlock, block_reasons: { vt_ip_malicious: vtIpMal, vt_file_malicious: vtFileMal, has_download: hasDownload, has_execution: hasExecution } } }];
